var mode='t2d',lastOut='';
function pad(n){return (n<10?'0':'')+n;}
function tick(){document.getElementById('now').textContent=Math.floor(Date.now()/1000);}
tick(); setInterval(tick,1000);
document.getElementById('copyNow').addEventListener('click',function(){
  WT.copy(document.getElementById('now').textContent);
  document.getElementById('note').textContent='Current timestamp copied.';
});
var tabs=document.getElementById('tabs');
tabs.addEventListener('click',function(e){
  var b=e.target.closest('button'); if(!b)return;
  [].forEach.call(tabs.querySelectorAll('button'),function(x){x.classList.remove('active');});
  b.classList.add('active'); mode=b.getAttribute('data-m');
  document.getElementById('p-t2d').style.display=mode==='t2d'?'':'none';
  document.getElementById('p-d2t').style.display=mode==='d2t'?'':'none';
  document.getElementById('rows').innerHTML=''; document.getElementById('note').textContent='';
  WT.resize();
});
function show(pairs){
  document.getElementById('rows').innerHTML=pairs.map(function(p){
    return '<div class="orow"><span>'+p[0]+'</span><b>'+p[1]+'</b></div>';
  }).join('');
  WT.resize();
}
function run(){
  var note=document.getElementById('note');
  if(mode==='t2d'){
    var raw=document.getElementById('ts').value.trim();
    if(!raw){document.getElementById('rows').innerHTML='';note.textContent='Enter a timestamp.';return;}
    if(!/^-?\d+$/.test(raw)){note.textContent='A Unix timestamp is a whole number of seconds. Check the value.';return;}
    var num=parseInt(raw,10);
    var msMode=document.getElementById('ms').checked;
    var d=new Date(msMode?num:num*1000);
    if(isNaN(d.getTime())){note.textContent='That number is out of range for a date.';return;}
    lastOut=d.toISOString();
    show([
      ['UTC', d.toUTCString()],
      ['Your local time', d.toString()],
      ['ISO 8601', d.toISOString()],
      ['Seconds', String(Math.floor(d.getTime()/1000))],
      ['Milliseconds', String(d.getTime())]
    ]);
    var diff=Math.floor((Date.now()-d.getTime())/1000);
    var ago=Math.abs(diff)<60?Math.abs(diff)+' seconds':Math.abs(diff)<3600?Math.round(Math.abs(diff)/60)+' minutes':Math.abs(diff)<86400?Math.round(Math.abs(diff)/3600)+' hours':Math.round(Math.abs(diff)/86400)+' days';
    note.textContent=diff>=0?'That is '+ago+' ago.':'That is '+ago+' from now.';
  } else {
    var ds=document.getElementById('d').value, tsv=document.getElementById('tm').value||'00:00:00';
    if(!ds){document.getElementById('rows').innerHTML='';note.textContent='Pick a date.';return;}
    var d2=new Date(ds+'T'+(tsv.length===5?tsv+':00':tsv));
    if(isNaN(d2.getTime())){note.textContent='That date and time could not be read.';return;}
    lastOut=String(Math.floor(d2.getTime()/1000));
    show([
      ['Seconds', String(Math.floor(d2.getTime()/1000))],
      ['Milliseconds', String(d2.getTime())],
      ['UTC', d2.toUTCString()],
      ['ISO 8601', d2.toISOString()]
    ]);
    note.textContent='Read as your local time zone, then converted.';
  }
}
document.getElementById('go').addEventListener('click',run);
document.getElementById('ts').addEventListener('input',run);
document.getElementById('ms').addEventListener('change',run);
['d','tm'].forEach(function(id){document.getElementById(id).addEventListener('input',run);});
document.getElementById('copyOut').addEventListener('click',function(){
  if(!lastOut){document.getElementById('note').textContent='Convert something first.';return;}
  var ok=WT.copy(lastOut);
  document.getElementById('note').textContent=ok?'Copied to clipboard.':'Copy failed, select the text instead.';
});
